import { createReadStream, statSync } from "node:fs";
import { createServer, type IncomingMessage, type ServerResponse } from "node:http";
import { URL } from "node:url";
import type { YoutubeProxyConfig } from "./config.js";
import { canonicalYoutubeUrl } from "./runner.js";
import type { YoutubeProcessor } from "./processor.js";
function send(r:ServerResponse,status:number,body:unknown){const b=Buffer.from(JSON.stringify(body));r.writeHead(status,{"content-type":"application/json; charset=utf-8","content-length":b.length,"cache-control":"no-store"});r.end(b)}
async function body(r:IncomingMessage,max:number){const xs:Buffer[]=[];let n=0;for await(const x of r){const b=Buffer.from(x);n+=b.length;if(n>max)throw new Error("BODY_TOO_LARGE");xs.push(b)}try{return JSON.parse(Buffer.concat(xs).toString())}catch{throw new Error("INVALID_JSON")}}
function valid(value:unknown){if(!value||typeof value!=="object"||Array.isArray(value))throw new Error("INVALID_REQUEST");const b=value as Record<string,unknown>;if(Object.keys(b).some(k=>!["requestId","chatId","userId","logId","url"].includes(k))||typeof b.requestId!=="string"||!/^youtube:[1-9]\d{0,19}:[1-9]\d{0,19}$/.test(b.requestId)||!["chatId","userId","logId"].every(k=>typeof b[k]==="string"&&/^[1-9]\d{0,19}$/.test(b[k] as string))||typeof b.url!=="string"||b.url.length>2048)throw new Error("INVALID_REQUEST");return {requestId:b.requestId,chatId:b.chatId as string,userId:b.userId as string,logId:b.logId as string,url:canonicalYoutubeUrl(b.url)}}
function auth(value:string|string[]|undefined,secret:string){const v=Array.isArray(value)?value[0]:value;return typeof v==="string"&&v.length===secret.length+7&&v.startsWith("Bearer ")&&v.slice(7)===secret}
export function createYoutubeServer(config:YoutubeProxyConfig,processor:YoutubeProcessor,secret:string){return createServer(async(req,res)=>{const u=new URL(req.url??"/","http://127.0.0.1");try{if(req.method==="GET"&&u.pathname==="/health")return send(res,200,{ok:true,service:"proxy-youtube"});if(req.method==="GET"&&u.pathname==="/ready"){const x=await processor.readiness();return send(res,x.ready?200:503,x)}if(!auth(req.headers.authorization,secret))return send(res,401,{error:{code:"UNAUTHORIZED"}});if(req.method==="POST"&&u.pathname==="/v1/self-test/readiness"){const x=await processor.readiness();return send(res,x.ready?200:503,x)}if(req.method==="POST"&&u.pathname==="/v1/youtube/jobs"){const x=processor.create(valid(await body(req,config.requestMaxBytes)));return send(res,x.created?202:200,x.job)}const m=u.pathname.match(/^\/v1\/youtube\/jobs\/([0-9a-f-]+)(\/file)?$/);if(!m)return send(res,404,{error:{code:"NOT_FOUND"}});const chat=u.searchParams.get("chatId")??"";if(m[2]&&req.method==="GET"){const job=processor.file(m[1]!,chat);if(!job)return send(res,404,{error:{code:"YOUTUBE_FILE_NOT_FOUND"}});const path=job.artifactPath!;const n=statSync(path).size;res.writeHead(200,{"content-type":"video/mp4","content-length":n,"cache-control":"no-store","x-content-type-options":"nosniff"});createReadStream(path).pipe(res);return}const x=req.method==="GET"?processor.get(m[1]!,chat):req.method==="DELETE"?processor.cancel(m[1]!,chat):undefined;return x?send(res,200,x):send(res,404,{error:{code:"YOUTUBE_JOB_NOT_FOUND"}})}catch(e){const code=((e as Error).message||"YOUTUBE_INTERNAL_ERROR").replace(/[^A-Z0-9_]/g,"_").slice(0,64);return send(res,code==="BODY_TOO_LARGE"?413:code.includes("QUEUE")?429:400,{error:{code}})}})}
